import unittest
from candidate import remove_duplicates

class TestRemoveDuplicates(unittest.TestCase):
    def test_normal_case_with_duplicates(self):
        self.assertEqual(remove_duplicates([1, 2, 3, 2, 4]), [1, 3, 4])

    def test_all_unique_elements(self):
        self.assertEqual(remove_duplicates([5, 6, 7, 8]), [5, 6, 7, 8])

    def test_all_duplicate_elements(self):
        self.assertEqual(remove_duplicates([1, 1, 2, 2, 3, 3]), [])

    def test_empty_list_input(self):
        self.assertEqual(remove_duplicates([]), [])

    def test_single_element_list(self):
        self.assertEqual(remove_duplicates([42]), [42])

    def test_negative_numbers_and_zeros(self):
        self.assertEqual(remove_duplicates([-5, 0, -5, 0, 1]), [1])

    def test_preserves_original_order(self):
        self.assertEqual(remove_duplicates([3, 1, 4, 1, 5, 9, 2, 6, 2]), [3, 4, 5, 9])

    def test_multiple_occurrences_of_single_element(self):
        self.assertEqual(remove_duplicates([7, 7, 7]), [])

    def test_none_value_input_raises_error(self):
        with self.assertRaises(TypeError):
            remove_duplicates(None)

    def test_non_iterable_input_raises_error(self):
        with self.assertRaises(TypeError):
            remove_duplicates(123)

    def test_mixed_positive_negative_and_zero(self):
        self.assertEqual(remove_duplicates([-1, -1, 0, 0, 1, 1]), [])

    def test_large_list_with_duplicates_removed(self):
        self.assertEqual(remove_duplicates([1] * 50 + [2] + [3] * 25 + [4]), [2, 4])

if __name__ == '__main__':
    unittest.main()
